import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.vLhlLNVn.js";const k=JSON.parse('{"title":"KeyChain","description":"","frontmatter":{},"headers":[],"relativePath":"configure/keychain.md","filePath":"configure/keychain.md"}'),n={name:"configure/keychain.md"};function o(s,e,p,h,l,d){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="keychain" tabindex="-1">KeyChain <a class="header-anchor" href="#keychain" aria-label="Permalink to &quot;KeyChain&quot;">​</a></h1><h3 id="set-a-key-pair-for-your-provider" tabindex="-1">Set a key pair for your provider <a class="header-anchor" href="#set-a-key-pair-for-your-provider" aria-label="Permalink to &quot;Set a key pair for your provider&quot;">​</a></h3><p>This plugin installs and uses our <a href="https://github.com/flipboxfactory/keychain" target="_blank" rel="noreferrer">KeyChain Plugin</a> to manage your key pairs. It&#39;s able to create key pairs using OpenSSL or import your existing key pairs.</p><div class="tip custom-block"><p class="custom-block-title">Recommended</p><p>Create a key pair for your provider. SAML protocol may sign and encrypt messages between the Identity Provider (IDP) and the Service Provider (SP). This makes the communication and transmission of the data more secure and any good IDP will support signing and encrypting message data. This requires a key pair.</p></div><h4 id="option-1-generate-key-pair" tabindex="-1">Option 1: Generate Key Pair <a class="header-anchor" href="#option-1-generate-key-pair" aria-label="Permalink to &quot;Option 1: Generate Key Pair&quot;">​</a></h4><p>When you are creating your provider, there is an option on the right sidebar to &quot;Generate key pair&quot;.</p><p>Clicking that button will generate a key pair for you using OpenSSL and some default settings.</p><ul><li>Control Panel path reference: <code>/admin/saml-sp/metadata/my-provider</code>.</li><li>Navigate (from sidebar): My Provider</li></ul><h4 id="option-2-create-a-key-pair-with-openssl" tabindex="-1">Option 2: Create a Key Pair with OpenSSL <a class="header-anchor" href="#option-2-create-a-key-pair-with-openssl" aria-label="Permalink to &quot;Option 2: Create a Key Pair with OpenSSL&quot;">​</a></h4><p>From the SAML plugin in the Craft admin, go to &#39;Create a new key pair&#39;. This form contains the same fields you may be familiar with when running the command via the CLI. Use a descriptive name to identify the key pair so you can match it to your provider later.</p><ul><li>Control Panel path reference: <code>/admin/saml-sp/keychain/new-openssl</code>.</li><li>Navigate (from sidebar): Keychain &gt; Dropdown button in the upper right &quot;Create New OpenSSL Key Pair&quot;</li></ul><h4 id="option-3-bring-your-own-key-pair-byok" tabindex="-1">Option 3: Bring your Own Key Pair (BYOK) <a class="header-anchor" href="#option-3-bring-your-own-key-pair-byok" aria-label="Permalink to &quot;Option 3: Bring your Own Key Pair (BYOK)&quot;">​</a></h4><p>Generate a key by running the following command in your terminal. Copy the key pairs.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> req</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x509</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 365</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nodes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sha256</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saml-sp.crt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -keyout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saml-sp.pem</span></span></code></pre></div><p>From the SAML plugin in the Craft admin, import the key pair at &#39;Create new key pair&#39;.</p><ul><li>Control Panel path reference: <code>/admin/saml-sp/keychain/new</code>.</li><li>Navigate (from sidebar): Keychain &gt; Button in the upper right &quot;Add New Key Pair&quot;</li></ul>',16)])])}const c=a(n,[["render",o]]);export{k as __pageData,c as default};
